  "settings.retentionOffsiteHint": "Una policy separata per il repo off-site, per tenerlo più a lungo come archivio. Tutto a 0 = mantieni ogni backup off-site (nessuna pulizia off-site).",
  "settings.ownRetentionTitle": "Regole di conservazione per origine",
  "settings.ownRetentionHint": "Ogni origine può seguire regole di conservazione proprie invece di quelle comuni qui sopra. Container e cartelle che cambiano ogni giorno possono tenere 7 backup giornalieri, le VM che cambiano di rado meno. Un'origine senza regole proprie usa quelle comuni.",
  "settings.ownRetention": "Regole di conservazione proprie",
  "settings.ownRetentionFor": "Regole di conservazione proprie per {source}",
  "settings.ownRetentionToggleHint": "Attivo: questa origine conserva i backup secondo le cinque regole qui sotto, che partono dai valori comuni. Disattivo: usa le regole comuni. Tutto a 0 conserva ogni backup di questa origine.",
  "settings.ownOffsiteRetention": "Regole di conservazione off-site proprie",
  "settings.ownOffsiteRetentionFor": "Regole di conservazione off-site proprie per {source}",
  "settings.ownOffsiteRetentionHint": "Ogni origine può conservare i backup del proprio repo off-site secondo regole proprie invece delle regole off-site comuni qui sopra. Un'origine senza regole proprie usa quelle comuni.",
  "settings.ownOffsiteRetentionToggleHint": "Attivo: il repo off-site di questa origine conserva i backup secondo le cinque regole qui sotto, che partono dai valori off-site comuni. Disattivo: usa le regole off-site comuni. Tutto a 0 conserva ogni backup off-site di questa origine.",
  "settings.retentionExtraTargets": "Le destinazioni off-site aggiuntive mantengono le proprie regole, che imposti nella pagina Off-site.",
  "settings.retentionOffsiteScope": "Queste regole valgono per la destinazione off-site primaria di ogni dominio, cioè l'indirizzo nel suo campo off-site. Ogni altra destinazione off-site, anche una creata da una destinazione, mantiene le proprie regole. Se lì ci sono solo zeri, BombVault non la pota mai.",
  "settings.retentionCombineInfo": "Le cinque regole si combinano con OR: uno snapshot sopravvive se anche una sola regola lo manterrebbe. Non si sommano a un numero fisso. Si applica separatamente a ogni elemento sottoposto a backup.",

  // Off-site (rclone)
  "rclone.title": "Off-site (rclone)",
  "rclone.hint": "Incolla una configurazione rclone per eseguire il backup nel cloud (Backblaze B2, S3, Google Drive, …). Viene memorizzata cifrata. SMB/NFS non richiedono rclone: monta la condivisione su Unraid e impostavi un percorso di backup.",
  "rclone.configured": "Remote configurati",
  "rclone.pathHint": "Poi imposta un percorso di backup su «rclone:<remote>:<bucket>/path» per inviare quel dominio off-site.",
  "cloud.title": "Credenziali cloud condivise (S3 / restic REST)",
  "cloud.hint": "Credenziali per backend restic remoti, senza rclone. Dopo il salvataggio, imposta un percorso di backup su un repo remoto, es. s3:s3.amazonaws.com/bucket/path, rest:http://host:8000/repo o sftp:user@host:/repo. I segreti sono memorizzati cifrati e non vengono più mostrati.",
  "cloud.secretSet": "salvato, lascia vuoto per mantenere",
  "cloud.storageClass.label": "Classe di archiviazione off-site",
  "cloud.storageClass.default": "(predefinito del provider)",
  "cloud.storageClass.hint": "Si applica solo ai backend S3 nativi (repository che iniziano con s3:). I livelli di archivio profondo (Glacier Flexible Retrieval, Deep Archive) non vengono offerti di proposito perché interrompono il ripristino di restic.",
  "cloud.credSets.title": "Set di credenziali aggiuntivi",
  "cloud.credSets.hint": "Assegna a una o più destinazioni esterne le proprie credenziali S3 o restic REST, invece di condividere quelle sopra.",
  "cloud.credSets.add": "Aggiungi set di credenziali",
  "cloud.credSets.name": "Nome",
  "cloud.credSets.none": "Nessun set di credenziali aggiuntivo ancora.",
  "cloud.credSets.kept": "{name} (credenziali mantenute)",
  "export.encrypt.hint": "I repository restic sono già cifrati. Questo cifra facoltativamente gli artefatti di esportazione in chiaro (tar.gz di container e VM con i relativi xml, e lo zip flash) con age, così da poterli archiviare o spostare fuori dal server in sicurezza.",
  "export.encrypt.ageInfo": "age (age-encryption.org) è uno strumento di cifratura file piccolo e moderno, un'alternativa più semplice a GPG per sigillare un file per uno o più destinatari.",
  "export.encrypt.enable": "Cifra le esportazioni con age",
  "export.encrypt.enableHint": "Se attivo, le esportazioni di container, VM e flash vengono sigillate con age prima di essere scritte su disco e ricevono il suffisso .age.",
  "export.encrypt.kitSealed": "Anche il kit di ripristino viene sigillato e arriva come bombvault-recovery-kit.md.age. Resta testo leggibile (ASCII armor), quindi puoi ancora incollarlo in un gestore di password o stamparlo, ma per aprirlo ti serve la tua chiave privata age: conserva quella chiave in un posto che non dipenda dal kit stesso.",
  "export.encrypt.recipients": "Destinatari age",
  "export.encrypt.recipientsHint": "Un destinatario per riga. Usa una chiave pubblica age (age1...) o una chiave pubblica SSH. Per decifrare fuori dal server serve la chiave privata corrispondente. Con la cifratura attiva e nessun destinatario valido, l'esportazione fallisce invece di scrivere testo in chiaro.",
  "export.encrypt.recipientsPlaceholder": "age1qz...\nssh-ed25519 AAAA...",
  "export.encrypt.recipientsRequired": "Aggiungi almeno un destinatario age, altrimenti l'esportazione cifrata fallirà.",
  "rclone.save": "Salva config",

