  "recovery.encUnknown": "Non è ancora possibile stabilirlo: i repository non si sono aperti, quindi la loro modalità di cifratura è sconosciuta. Correggi la posizione qui sopra e ricontrolla, oppure impostala tu se la conosci già.",
  "recovery.encConflict": "I tuoi repository si contraddicono: alcuni sono cifrati, altri no. Una sola impostazione non può aprirli entrambi: punta quello discordante su una posizione nuova e vuota, oppure ripristina solo dal gruppo coerente.",
