  "recovery.encDetectHint": "La cifratura non è una preferenza: un repository viene creato con una password (derivata dalla tua APP_KEY) oppure senza, e questo non cambia mai più. BombVault apre i repository configurati per vedere quale dei due casi vale, così ripristinare su una macchina nuova non richiede di indovinare. Un repository irraggiungibile viene segnalato come sconosciuto, mai come non cifrato.",
