  "dbdump.saveToFolder": "Salva in una cartella",
  "dbdump.saveHint": "Scrive il dump come file nella cartella scelta sul server, di proprietà di nobody:users così puoi aprirlo dalla condivisione di rete. Il file contiene tutte le tabelle e gli hash delle password degli utenti del database; tienilo dove arrivi solo tu.",
  "dbdump.saveCancelHint": "Annullare ferma il salvataggio e rimuove il file incompleto.",
  "dbdump.savedTo": "Salvato in {path}",
  "dbdump.import": "Importa in un database nuovo",
  "dbdump.importConfirm": "Importare questo dump {engine} {version} in {container}? BombVault ferma il contenitore, sposta di lato la sua cartella dati (viene conservata, non si cancella nulla), avvia il contenitore con una cartella dati vuota e importa il dump. Le applicazioni che usano questo database ne vedranno lo stato al momento del dump.",
  "dbdump.importConfirmNoVersion": "Importare questo dump {engine} in {container}? BombVault ferma il contenitore, sposta di lato la sua cartella dati (viene conservata, non si cancella nulla), avvia il contenitore con una cartella dati vuota e importa il dump. Le applicazioni che usano questo database ne vedranno lo stato al momento del dump.",
  "dbdump.importNoVersion": "Questo dump non registra la versione del suo database. L'importazione fallisce se il server non riesce a leggerlo.",
  "dbdump.importStops": "one=Durante l'importazione BombVault ferma anche {apps} e poi la riavvia. Se l'importazione fallisce dopo essere iniziata, i vecchi dati restano da parte e l'applicazione ferma.|many=Durante l'importazione BombVault ferma anche queste applicazioni: {apps}. Poi le riavvia. Se l'importazione fallisce dopo essere iniziata, i vecchi dati restano da parte e le applicazioni ferme.|other=Durante l'importazione BombVault ferma anche queste applicazioni: {apps}. Poi le riavvia. Se l'importazione fallisce dopo essere iniziata, i vecchi dati restano da parte e le applicazioni ferme.",
  "dbdump.importDone": "Database importato.",
  "dbdump.importRefused.busy": "È in corso un altro backup o ripristino. Riprova quando sarà finito.",
  "dbdump.importRefused.notRunning": "Avvia prima il contenitore; l'importazione ha bisogno del server in esecuzione.",
  "dbdump.importRefused.engineMismatch": "Questo dump proviene da un tipo di database diverso da quello che il contenitore esegue.",
  "dbdump.importRefused.noDataMount": "BombVault non raggiunge la cartella dati di questo contenitore, quindi non può metterla di lato in sicurezza. Importa il dump a mano come descrive il kit di ripristino.",
  "dbdump.importRefused.version": "Il server esegue la versione {server}, il dump viene da {dump}. Per questa importazione usa un'immagine con versione {dump} o più recente.",
  "dbdump.importRefused.versionSameMajor": "Il server esegue la versione {server}, il dump viene da {dump}. MySQL e MariaDB importano un dump solo nella versione maggiore da cui proviene, quindi per questa importazione usa un'immagine con versione {dump}.",
  "dbdump.importRefused.damaged": "Questo dump è danneggiato e non può essere importato.",
