  "dbdump.restoreLiveWarn": "I file di questo database vengono copiati con il server in esecuzione, quindi i file ripristinati potrebbero non avviarsi puliti. Se non lo fanno, importa il dump preso con questo backup, elencato qui sotto.",
  "dbdump.restoreNoneWarn": "La cartella dati di questo database non è nel backup. Il ripristino riporta il contenitore con un database vuoto; poi importa un dump dall'elenco qui sotto.",
