  // Restore from another BombVault repo — Recovery page (#61 task 11)
  "recovery.foreignTitle": "Ripristina da un altro repo BombVault",
  "recovery.abTitle": "Importa dal plugin Appdata.Backup",
  "recovery.abIntro": "Trasforma gli archivi scritti dal plugin Appdata.Backup in punti di ripristino dei container corrispondenti, ognuno con la data in cui il plugin l'ha creato. Gli archivi vengono solo letti, mai modificati o eliminati. Ognuno viene estratto accanto al repository, salvato e la copia estratta viene rimossa, quindi lì serve spazio per l'archivio più grande.",
