  "recovery.abImporting": "Importazione…",
  "recovery.abImportFailed": "Impossibile avviare l'importazione.",
  "recovery.abDone": "Importazione completata. I punti di ripristino sono nei backup di ogni container.",
  "recovery.abAllFailed": "Nessun archivio è stato importato. Il registro attività dice perché.",
  "recovery.abSomeFailed": "Alcuni archivi non sono stati importati. Il registro attività dice perché.",
  "recovery.foreignIntro": "Recupera singoli container, VM, set di cartelle o dataset ZFS dai backup di un'altra istanza BombVault: connettiti in sola lettura, sfoglia il contenuto, ripristina ciò che scegli. L'altro repository viene solo letto, lì non cambia nulla, e le tue impostazioni di backup restano intatte.",
  "recovery.foreignStepConnect": "Connettiti all'altro repository",
  "recovery.foreignStepBrowse": "Sfoglia e ripristina",
  "recovery.foreignLocation": "Posizione del repository",
  "recovery.foreignLocationHint": "Una cartella sotto il mount dell'host. Monta su questo host la condivisione con i backup dell'altro server e puntala qui. Il repository deve essere montato localmente (qui non si accettano URL di repo remoti).",
  "recovery.foreignKey": "APP_KEY dell'altra istanza",
  "recovery.foreignKeyHint": "La chiave di 64 caratteri dal recovery kit dell'ALTRA istanza. La tua chiave resta intatta.",
  "recovery.foreignCredsIntro": "Sembra un repository remoto, quindi servono le credenziali del backend dell'ALTRO server. Valgono solo per questa sessione e non vengono mai salvate. Le tue credenziali off-site non vengono riutilizzate qui di proposito: verrebbero inviate a un indirizzo che hai appena digitato.",
  "recovery.foreignS3KeyId": "ID chiave di accesso (S3/B2)",
