  "recovery.foreignRestHint": "Solo per un repository «rest:» (un server restic REST). Lascia vuoto per S3, B2 o SFTP.",
  "recovery.foreignConnect": "Connetti",
  "recovery.foreignConnecting": "Connessione…",
  "recovery.foreignConnected": "Connesso. Il repository è leggibile.",
  "recovery.foreignClose": "Disconnetti",
  "recovery.foreignNotConnected": "Connettiti prima a un repository qui sopra.",
  "recovery.foreignEmpty": "Il repository è leggibile ma non contiene backup BombVault.",
  "recovery.foreignDbDumps": "one={n} dump di database in questo repository. Prendilo con la CLI di restic come descrive il kit di ripristino.|many={n} dump di database in questo repository. Prendine uno con la CLI di restic come descrive il kit di ripristino.|other={n} dump di database in questo repository. Prendine uno con la CLI di restic come descrive il kit di ripristino.",
  "recovery.dumpOnlyTitle": "Database salvati solo come dump",
  "recovery.dumpOnlyHint": "Questi contenitori non hanno un backup dei file, solo dump del database. Ripristina ciascuno e importa il suo dump prima di avviare le applicazioni che lo usano.",
  "recovery.restoreAndImport": "Ripristina e importa",
  "recovery.dumpOnlySkipped": "one={n} database salvato solo come dump resta fuori qui. Ripristinalo e importalo dal suo elenco.|many={n} database salvati solo come dump restano fuori qui. Ripristinali e importali dal loro elenco.|other={n} database salvati solo come dump restano fuori qui. Ripristinali e importali dal loro elenco.",
  "recovery.foreignLatest": "Backup più recente",
  "recovery.foreignTargetFolder": "Cartella di destinazione",
