  "recovery.foreignSubfolderHint": "Ripristina nella cartella di destinazione solo le sottocartelle o i file selezionati di questo set, ad esempio uno stack da un backup completo di appdata.",
  "recovery.foreignAppdataDest": "Destinazione appdata",
  "recovery.foreignAppdataDestHint": "Dove vengono ripristinati gli appdata del contenitore. Lascia vuoto per l'impostazione predefinita. Un contenitore di cui è stato eseguito il backup da un pool che questo server non ha (ad esempio /mnt/zfs) viene rimappato qui in modo che finisca nel posto giusto.",
  "recovery.foreignOverwrite": "Sovrascrivi se la destinazione contiene già dati",
